def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Defect in the last three rounds to maximize endgame payoff.
    if n >= 97:
        return 'D'
    my_last, op_last = history[-1]
    if op_last == 'D':
        opp_def = sum(1 for _, o in history if o == 'D')
        # Forgive if opponent has defected very rarely.
        if opp_def <= max(1, n // 10):
            return 'C'
        # If opponent has defected in the last two rounds, retaliate.
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        # If we defected last round and opponent's overall defection rate is moderate,
        # try cooperating to break the cycle.
        if my_last == 'D' and opp_def <= n // 2:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated last round.
        # If we have been defecting recently and opponent still cooperates, exploit.
        if n >= 3:
            recent_my = [m for m, _ in history[-3:]]
            recent_op = [o for _, o in history[-3:]]
            if all(m == 'D' for m in recent_my) and all(o == 'C' for o in recent_op):
                return 'D'
        return 'C'
